import { readFile } from "node:fs/promises";
import openapiTS, { astToString } from "openapi-typescript";
const output = astToString(
  await openapiTS(new URL("../contracts/tax-preview.openapi.json", import.meta.url)),
);
const current = await readFile(
  new URL("../src/types/tax-preview.generated.ts", import.meta.url),
  "utf8",
);
if (
  current.replaceAll("\r\n", "\n") !==
  (
    "/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n" +
    output
  ).replaceAll("\r\n", "\n")
) {
  console.error("Generated preview types are stale. Run npm run api:generate.");
  process.exitCode = 1;
} else console.log("Generated preview types match the preview contract.");
